  "set.weitergebenText": { de: "Die App ist eine einzige Datei. Du kannst sie exportieren und weitergeben; ihre Echtheit lässt sich gegen das signierte Manifest prüfen.", en: "The app is a single file. You can export and share it; its authenticity can be checked against the signed manifest." },
  "set.appExportieren": { de: "App exportieren", en: "Export app" },
