  "set.wasGeraete": { de: "Geräte hinzufügen", en: "Adding devices" },
  "set.nfNicht": { de: "Nicht eingerichtet. Ohne Nachfolge ist dein Zugang bei Geräteverlust endgültig weg.", en: "Not set up. Without succession your access is gone for good if you lose your device." },
  "set.nfPlan": { de: "{schwelle} von {von} Vertrauten, Frist {frist} Tage, Wartezeit {warte} Tage.", en: "{schwelle} of {von} trusted people, inactivity period {frist} days, waiting time {warte} days." },
  // Dialoge statt prompt()/confirm() (C-1c)
  "set.nachfolgeDialog": { de: "Nachfolge einrichten", en: "Set up succession" },
  "set.vertrauteText": { de: "Mindestens 3 Personen, die sich NICHT kennen und FreedomStack nutzen.", en: "At least 3 people who do NOT know each other and use FreedomStack." },
